import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { userLogic } from 'scenes/userLogic'

import type { UserType } from '~/types'

import { onboardingEventUsageLogic } from '../../onboardingEventUsageLogic'

// Enough to outlast any realistic run history on one browser without letting the persisted list
// grow forever.
const SEEN_HANDOFF_DOC_KEYS_CAP = 20

/** Where a run is executing: in the user's terminal, or on our infrastructure. */
export type WizardSyncMode = 'cloud' | 'local'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicValues {
    user: UserType | null // userLogic
    dialogOpen: boolean
    dismissedKey: string | null
    handoffDoc: {
        key: string
        text: string
    } | null
    inlineCloudPanelMounted: boolean
    inlineLocalPanelMounted: boolean
    inlinePanelCounts: Record<WizardSyncMode, number>
    inlinePanelMounted: boolean
    seenHandoffDocKeys: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicActions {
    reportWizardSyncHandoffDocOpened: (props: {
        mode: 'cloud' | 'local'
        runKey: string
        trigger: 'auto' | 'button'
    }) => {
        mode: 'cloud' | 'local'
        runKey: string
        trigger: 'auto' | 'button'
    } // onboardingEventUsageLogic
    claimInlinePanel: (mode: WizardSyncMode) => {
        mode: WizardSyncMode
    }
    closeDialog: () => {
        value: true
    }
    closeHandoffDoc: () => {
        value: true
    }
    dismiss: (key: string) => {
        key: string
    }
    handoffDocReceived: (doc: { key: string; startedByEmail: string | null; text: string }) => {
        key: string
        startedByEmail: string | null
        text: string
    }
    openDialog: () => {
        value: true
    }
    openHandoffDoc: (doc: { key: string; text: string }) => {
        key: string
        text: string
    }
    releaseInlinePanel: (mode: WizardSyncMode) => {
        mode: WizardSyncMode
    }
    restore: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        inlineCloudPanelMounted: (inlinePanelCounts: Record<WizardSyncMode, number>) => boolean
        inlineLocalPanelMounted: (inlinePanelCounts: Record<WizardSyncMode, number>) => boolean
        inlinePanelMounted: (inlineCloudPanelMounted: boolean, inlineLocalPanelMounted: boolean) => boolean
    }
}

export type wizardSyncUiLogicType = MakeLogicType<
    wizardSyncUiLogicValues,
    wizardSyncUiLogicActions,
    Record<string, any>,
    wizardSyncUiLogicMeta
>

/**
 * UI state for the detached wizard sync widget, shared app-wide (mounted by WizardSyncFab):
 *   - `dismissedKey`: the run the user minimized. Keyed by run id (cloud) or session id (local) so a
 *     fresh run is never born already-minimized, and a minimize survives navigation (persisted).
 *   - `dialogOpen`: whether the "all the details" dialog is showing.
 *   - `inlineCloudPanelMounted` / `inlineLocalPanelMounted`: a scene is already showing a run inline
 *     (the onboarding install step, the inbox), so the detached surface for *that* run stands down
 *     rather than showing it twice. Refcounted: a boolean would let one panel's unmount un-hide the
 *     widget while another is still showing. Tracked per mode because cloud and local runs can be in
 *     flight at once, and a surface that only ever renders one of them must not silence the other.
 *   - `handoffDoc`: the markdown handoff doc dialog currently showing (content is fed by whichever
 *     source announced or opened it). `seenHandoffDocKeys` (persisted) makes the announce-driven
 *     open a strictly once-per-run event: SSE replays, remounts, and reloads re-announce the same
 *     doc, and only the first announcement may pop the dialog. The button reopens it at will.
 *
 * The widget itself owns no run data; the per-mode inner components feed it the normalized progress.
 */
export const wizardSyncUiLogic = kea<wizardSyncUiLogicType>([
    path(['scenes', 'onboarding', 'wizardSyncUiLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
        actions: [onboardingEventUsageLogic, ['reportWizardSyncHandoffDocOpened']],
    })),
    actions({
        dismiss: (key: string) => ({ key }),
        restore: true,
        openDialog: true,
        closeDialog: true,
        claimInlinePanel: (mode: WizardSyncMode) => ({ mode }),
        releaseInlinePanel: (mode: WizardSyncMode) => ({ mode }),
        // A run's handoff doc was delivered (live session push, SSE replay, or a persisted
        // finished-run handle restored on pageload). Announcements are idempotent; the listener
        // decides whether this one gets the one-time auto-open.
        handoffDocReceived: (doc: { key: string; text: string; startedByEmail: string | null }) => doc,
        openHandoffDoc: (doc: { key: string; text: string }) => doc,
        closeHandoffDoc: true,
    }),
    reducers({
        dismissedKey: [
            null as string | null,
            { persist: true },
            {
                dismiss: (_, { key }) => key,
                restore: () => null,
            },
        ],
        dialogOpen: [
            false,
            {
                openDialog: () => true,
                closeDialog: () => false,
                restore: () => false,
            },
        ],
        inlinePanelCounts: [
            { cloud: 0, local: 0 } as Record<WizardSyncMode, number>,
            {
                claimInlinePanel: (state, { mode }) => ({ ...state, [mode]: state[mode] + 1 }),
                releaseInlinePanel: (state, { mode }) => ({ ...state, [mode]: Math.max(0, state[mode] - 1) }),
            },
        ],
        handoffDoc: [
            null as { key: string; text: string } | null,
            {
                openHandoffDoc: (_, { key, text }) => ({ key, text }),
                closeHandoffDoc: () => null,
            },
        ],
        seenHandoffDocKeys: [
            [] as string[],
            { persist: true },
            {
                // Any open counts as seen — a doc the user already read through the button must not
                // auto-open later.
                openHandoffDoc: (state, { key }) =>
                    state.includes(key) ? state : [...state, key].slice(-SEEN_HANDOFF_DOC_KEYS_CAP),
            },
        ],
    }),
    selectors({
        inlineCloudPanelMounted: [
            (s) => [s.inlinePanelCounts],
            (inlinePanelCounts: Record<WizardSyncMode, number>): boolean => inlinePanelCounts.cloud > 0,
        ],
        inlineLocalPanelMounted: [
            (s) => [s.inlinePanelCounts],
            (inlinePanelCounts: Record<WizardSyncMode, number>): boolean => inlinePanelCounts.local > 0,
        ],
        /** Any run is shown inline — for surfaces that don't distinguish which one, like the nav item. */
        inlinePanelMounted: [
            (s) => [s.inlineCloudPanelMounted, s.inlineLocalPanelMounted],
            (inlineCloudPanelMounted: boolean, inlineLocalPanelMounted: boolean): boolean =>
                inlineCloudPanelMounted || inlineLocalPanelMounted,
        ],
    }),
    listeners(({ actions, values }) => ({
        handoffDocReceived: ({ key, text, startedByEmail }) => {
            if (values.seenHandoffDocKeys.includes(key)) {
                return
            }
            // A teammate's run: popping a dialog because someone else's terminal finished would be
            // an interruption, not a handoff. They still get the button on the run's surfaces.
            // Not marked seen, so the doc can still auto-open for the teammate who did run it.
            const ownEmail = values.user?.email
            if (startedByEmail && ownEmail && startedByEmail !== ownEmail) {
                return
            }
            actions.openHandoffDoc({ key, text })
            // Announcements only come from local runs (cloud runs surface their doc via the button).
            actions.reportWizardSyncHandoffDocOpened({ runKey: key, mode: 'local', trigger: 'auto' })
        },
    })),
])
